// ============================================================================
// STAGE 2 OF OPTIMIZATION TREASURE HUNT: Deterministic Margin Scoring
// Computes match_score (70-100) from credit buffer and caps the batch size so
// we only invoke OpenAI gpt-4o-mini on the top 5 pairs.
// ============================================================================
const items = $input.all();

return items.slice(0, 5).map(item => {
  const d = item.json;
  const creditBuffer = Number(d.credit_score) - 700;
  const matchScore = Math.min(100, Math.max(70, 75 + Math.floor(creditBuffer / 5)));

  return {
    json: {
      ...d,
      match_score: matchScore
    }
  };
});

